package OPerators;

public class OPeratorTask2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stud
		//prefix and suffix
		int A  = 20;
	int	value1 = A++;
	System.out.println("value1 = "+value1+",A = "+A);
	int	value2 = ++A;
	System.out.println("value2 = "+value2+",A = "+A);
	int	value3 = A--;
	System.out.println("value3 = "+value3+",A = "+A);
	int	value4 = --A;
	System.out.println("value4 = "+value4+",A = "+A);

	}

}
